  insert into public.brands (name, website, description, country, status) values ('Cloud of Goods', 'https://www.cloudofgoods.com', 'Travel and mobility gear rental marketplace founded by Punsri Abeywickrema and headquartered in Coconut Creek, Florida, renting mobility scooters, wheelchairs, strollers, cribs, car seats and medical equipment through local partners, delivered to hotels, vacation rentals, homes, attractions, cruise ports and airports.', 'United States', 'published') returning id into bid;
