  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cloud of Goods Affiliate Program', 'https://www.cloudofgoods.com/agent-signup', 'https://www.cloudofgoods.com/agent-signup', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cloudofgoods.com/agent-signup', 'official_site', 'affiliate', 'Cloud of Goods'' official affiliate page states verbatim: ''Earn commission on every completed order. No caps on how much you can earn.'' Its FAQ sets a special 12% rate until September 2027 for anyone joining before December 31, 2026, resetting to a standard 10% rate after that, with real-time tracking and automated monthly payouts.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cloudofgoods.com/agent-signup', 'official_site', 'ugc_collab', 'The same page opens the program to travel agents, hotel concierges, tour operators, content creators, bloggers and influencers, but names only three example partners (one travel influencer, one resort concierge, one travel agent); searches for sponsored creator content surfaced no paid-partnership posts, indicating a thin creator footprint next to its B2B channels.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cloudofgoods.com/agent-signup', 'official_site', 'contact', 'The affiliate page footer publishes info@cloudofgoods.com and the company''s Coconut Creek, FL address, and sign-up is a free affiliate account created ''in under 2 minutes'' with no additional fees.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 14, 12, 9, 4, '{"compensation": "10% standard commission (12% promo rate into September 2027) on every completed rental order, explicitly stated as uncapped on the brand''s own page, with recurring earnings as customers re-rent.", "contact_access": "A published contact email on the official program page plus a two-minute self-serve sign-up \u2014 near top band per the rubric.", "credibility": "Established rental marketplace with national PR coverage, a BBB profile and delivery operations across many US destination cities.", "niche_fit": "Gear rental is a genuine travel-creator niche (family travel, accessible travel, cruises, theme parks), though it is a service rather than a shoppable product.", "opportunity_availability": "Open sign-up today for creators, bloggers and influencers with no fees and no stated follower minimum.", "ugc_evidence": "A formal affiliate program that explicitly courts travel influencers on Instagram, TikTok and YouTube, but with only a handful of named example partners so far."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Luggage Forward', 'https://www.luggageforward.com', 'Door-to-door luggage and sports-equipment shipping service founded in 2004 and based in Boston, Massachusetts, that collects suitcases, golf clubs, skis and other travel items from a customer''s doorstep and delivers them to their destination; it positions itself as an official luggage shipping partner for luxury cruise lines and tour operators.', 'United States', 'published') returning id into bid;
