  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 8, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: low (see evidence). Rate as reported by https://www.luggageforward.com/affiliates/.', 'https://www.luggageforward.com/affiliates/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Luggage Forward Affiliate Program', 'https://www.luggageforward.com/affiliates/', 'https://www.luggageforward.com/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.luggageforward.com/affiliates/', 'official_site', 'affiliate', 'Luggage Forward''s official affiliate page answers its ''How Much Can I Earn?'' section with: ''As much as you want. Commissions start at 8% and our average booking is around $400'', with commissions paid quarterly once earnings pass $25 — an earnings question answered with no limit stated.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.luggageforward.com/legal/affiliate-terms/', 'official_site', 'affiliate', 'The brand''s published Affiliate Terms and Conditions confirm the mechanics behind the page: an 8% commission on money received from eligible transactions, remitted quarterly within 30 days of quarter end once the balance exceeds $25, by check in US dollars.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/p/DcXqhozG-PM/', 'listing', 'ugc_collab', 'The program is built for travel agents rather than social creators — its own materials address agents throughout — and a search for creator promotion surfaced only a single promotional Instagram post by one travel creator (@pixelpathsw), indicating a very small creator footprint.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/248701/luggage-forward-affiliate-program', 'listing', 'general', 'Sovrn Commerce''s merchant profile describes Luggage Forward as founded in 2004 and based in Boston, Massachusetts, specializing in door-to-door luggage and sports-equipment shipping, and also lists the program for affiliate marketers on its network.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 8, 12, 8, 8, 4, '{"compensation": "8% commission on high-value bookings (average around $400 per the brand) with the earnings question answered ''As much as you want'' \u2014 no cap stated \u2014 though payouts are quarterly rather than monthly.", "contact_access": "A public registration route from the official page, but no published partnerships email \u2014 mid-range per the rubric.", "credibility": "Operating since 2004 with cruise-line and tour-operator partnerships and a long review history.", "niche_fit": "Luggage shipping is a natural fit for cruise, luxury and family travel creators, though it is a logistics service rather than a product haul niche.", "opportunity_availability": "Registration is open now from the affiliate page; the program also runs through Sovrn Commerce.", "ugc_evidence": "A real, long-running affiliate program with banners, links and an onsite booking app, but designed around travel agents, so the creator-specific layer is minimal."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lightspeed Aviation', 'https://www.lightspeedaviation.com', 'Premium aviation headset maker whose affiliate program lets pilots and aviation creators earn commission promoting its premium headsets through a custom referral URL, with monthly payouts via PayPal.', 'United States', 'published') returning id into bid;
