  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://go.lightspeedaviation.com/affiliate-program', 'official_site', 'affiliate', 'Lightspeed''s official affiliate page answers ''How much can I earn?'' with: affiliates ''earn upwards of 10% commission sales on premium Lightspeed headsets. Affiliates have unlimited earning potential - how much you promote, share, and earn is based on your efforts'', paid monthly for approved sales.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://go.lightspeedaviation.com/affiliate-program', 'official_site', 'ugc_collab', 'The same page shows a deliberately small, professional program: applications are reviewed, affiliates must supply Tax ID documents, and the brand anticipates a minimum of one headset sale per month (12 per year) to stay in the program — a restricted pool of pilot-creators rather than an open influencer roster.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 16, 10, 13, 7, 7, 4, '{"compensation": "Upwards of 10% commission on premium-priced headsets with ''unlimited earning potential'' stated verbatim on the brand''s own page \u2014 high order values make each sale meaningful.", "contact_access": "An application route from the official program page, but no published partnerships email \u2014 mid-range per the rubric.", "credibility": "A long-established premium brand in general aviation with products sold direct through its own store.", "niche_fit": "Aviation is a narrow travel-adjacent niche \u2014 an excellent fit for pilot and aviation creators, a weak fit for general travel UGC.", "opportunity_availability": "Applications are open, subject to review and Tax ID documentation, with a soft expectation of one headset sale per month.", "ugc_evidence": "A structured affiliate program with custom URLs and a dashboard, aimed at product-owning pilots who create content."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bio2 SunCare', 'https://bio2suncare.com', 'US suncare and skincare brand built on medical-grade formulations made in the USA at FDA-registered facilities, sold through its own website; its affiliate program also covers sister brand 7 Good Cows, a natural tallow-based skincare line, so affiliates can promote both brands under one program.', 'United States', 'published') returning id into bid;
