  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bio2 Sun Care Affiliate Program', 'https://bio2suncare.com/affiliate-welcome-letter/', 'https://bio2suncare.com/affiliate-welcome-letter/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bio2suncare.com/affiliate-welcome-letter/', 'official_site', 'affiliate', 'Bio2 SunCare''s official affiliate welcome letter states: ''Our standard affiliate commission is 15% — and there''s no limit to how many sales you can make'', and its FAQ answers the earnings question with: ''the sky is the limit! We do not cap commissions and we even pay for repeat customers'' — plus a 5% lifetime commission on repeat purchases, a 45-day cookie and monthly PayPal payouts from a $15 threshold.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bio2suncare.com/affiliate-welcome-letter/', 'official_site', 'ugc_collab', 'The same letter shows a small, personally run program still being built: affiliates are invited to ''Drop us a email or give us a call'' (210-920-5877) for help with a plan, the brand says ''We are building a community that grows together'', and standout affiliates are invited into VIP tiers, multi-level pathways and brand ambassador roles.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bio2suncare.com/affiliate-welcome-letter/', 'official_site', 'contact', 'The page publishes sales@bio2suncare.com (for W-9 forms and affiliate questions) and a phone number with text/voice hours, and registration requires a PayPal email for payouts.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 16, 11, 8, 3, '{"compensation": "15% standard commission plus 5% lifetime commission on repeat purchases, with an explicit ''We do not cap commissions'' statement on the brand''s own page \u2014 one of the strongest published offers in this batch.", "contact_access": "A published affiliate email and phone number with personal onboarding help offered on the program page itself.", "credibility": "Small US brand with FDA-registered manufacturing claims but limited independent coverage so far.", "niche_fit": "Suncare-led skincare with medical-grade positioning fits skincare and outdoor/travel beauty routines well.", "opportunity_availability": "Registration is open now from the welcome letter, with no inventory, minimums or big-influencer requirement (''We don''t reserve our program only for big influencers'').", "ugc_evidence": "A real affiliate program with multi-level pathways and ambassador/event roles for proven affiliates, run hands-on by the brand team."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Elle Jae Essentials', 'https://ellejaeessentials.com', 'Flint, Michigan all-natural skin, hair and body care brand founded in 2017 by La''Asia Johnson, selling handmade body butters, body oils, body washes, scrubs, candles and beard care online, on Etsy and from its own Flint boutique, where customers can mix custom products at an in-store mixology table.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
