  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'info@ElleJaeEssentials.com', null, 'https://theflintcouriernews.com/flint-area-business-owner-sent-by-facebook-owners-to-advocate-for-small-businesses-in-the-face-of-potential-changes/', 'needs_review', null);
