  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Elle Jae Essentials Brand Ambassador Program', 'https://ellejaeessentials.com/pages/brand-ambassador-application', 'https://ellejaeessentials.com/pages/brand-ambassador-application', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ellejaeessentials.com/pages/brand-ambassador-application', 'official_site', 'affiliate', 'Elle Jae Essentials'' official Brand Ambassador FAQ answers ''Is there a max of how much I can earn?'' with: ''No, there is no limit on the amount of money you can earn as an Elle Jae Brand Ambassador. The more traffic you drive, the more cah you earn!'' The program is free, open to anyone in the US, pays out every 1st of the month and includes sales training — but no commission percentage is published on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://flintside.com/How-one-Flint-business-owner-is-whipping-up-self-care/', 'listing', 'general', 'Flintside profiles founder La''Asia Johnson, who created her first body butter in 2017 and built the brand from home production to a mall kiosk and Flint storefront, selling handmade body care and employing local staff.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/reel/Dfpb5BfhUlU/', 'listing', 'ugc_collab', 'The brand''s own Instagram account (@ellejaeessentials) shows roughly 9.2K followers on a recent boutique walkthrough reel — a small, local-scale social footprint consistent with a founder-led ambassador program rather than a saturated creator roster.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theflintcouriernews.com/flint-area-business-owner-sent-by-facebook-owners-to-advocate-for-small-businesses-in-the-face-of-potential-changes/', 'listing', 'contact', 'The Flint Courier News publishes owner La''Asia Johnson''s contact details for the business: phone 810-814-1443 and email info@ElleJaeEssentials.com.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 8, 9, 8, 3, '{"compensation": "An explicit no-limit earnings answer in the official FAQ, but no published commission percentage, so this stays low per the rubric.", "contact_access": "A public ambassador application page plus a published owner email and phone in local press \u2014 mid-range per the rubric.", "credibility": "Founder-led Flint brand operating since 2017 with its own boutique and local press coverage, but a small footprint beyond Michigan.", "niche_fit": "Handmade natural body care and skincare is a clear clean-beauty UGC niche, with highly demonstrable products.", "opportunity_availability": "Applications are open now, free, US-wide, with training offered to ambassadors.", "ugc_evidence": "A named Brand Ambassador program with monthly payouts and social-media sales training, run at indie scale by the founder''s team."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Beauty by Earth', 'https://www.beautybyearth.com', 'Clean beauty brand founded in January 2014 by Prudence Millsap and bootstrapped without outside funding, selling natural skincare, self-tanner, hair and body care made in the USA and Leaping Bunny certified; the brand cites 2+ million orders and runs its creator monetization entirely through gifting and affiliate commission rather than paid campaigns.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'jenny@beautybyearth.com', null, 'https://manage.kmail-lists.com/subscriptions/web-view?a=TGfb8g&c=01GR22TSEK6881V938KHFWBB9W&k=0664311d616391879467f1f02719dc67&m=01GTFD7VRDQ00VT23YZK1Y2Q78&r=VaRDDVw', 'needs_review', null);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.beautybyearth.com/pages/turn-your-content-into-revenue', 'https://www.beautybyearth.com/pages/turn-your-content-into-revenue', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote / ShareASale', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.beautybyearth.com/pages/turn-your-content-into-revenue.', 'https://www.beautybyearth.com/pages/turn-your-content-into-revenue', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Beauty by Earth Affiliate Program (UpPromote / ShareASale)', 'https://www.beautybyearth.com/pages/turn-your-content-into-revenue', 'https://www.beautybyearth.com/pages/turn-your-content-into-revenue', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.beautybyearth.com/pages/turn-your-content-into-revenue', 'official_site', 'affiliate', 'Beauty by Earth''s official creator page offers ''10% Per Sale'' with a progressive commission structure and states verbatim under Unlimited Referrals: ''We don''t believe in ceilings, caps, limitations or maximums. Drive traffic and reap the rewards for every sale you refer!'' The program runs on UpPromote (also promotable via ShareASale) with bi-weekly PayPal payouts.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://manage.kmail-lists.com/subscriptions/web-view?a=TGfb8g&c=01GR22TSEK6881V938KHFWBB9W&k=0664311d616391879467f1f02719dc67&m=01GTFD7VRDQ00VT23YZK1Y2Q78&r=VaRDDVw', 'listing', 'affiliate', 'The brand''s own affiliate newsletter shows higher tiers above the standard rate — 20% commission on Essentials Club and Premium Line sales (versus standard 10%) and a 20% Bundle Builder rate with a $50 bonus for the first five sales — and names its affiliate manager (Jenny, jenny@beautybyearth.com) with weekly affiliate meetups.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.beautybyearth.com/collections/gifts', 'official_site', 'ugc_collab', 'The brand''s own collaboration FAQ states: ''As a small business, we don''t currently offer paid content campaigns, but would be happy to send gifted products in exchange for posts or videos. You can also sign up to be an affiliate with us and earn cash when you bring in sales!'' No creator counts are published, so creator saturation is marked unknown rather than assumed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://the10thhouse.femalefoundercollective.com/education/prudence-millsap-firesidechat', 'listing', 'general', 'The Female Founder Collective profile recounts founder Prudence Millsap launching Beauty by Earth in January 2014, bootstrapped with no outside funding, and growing from zero to 50,000 sales in its first year on Amazon.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 15, 11, 9, 4, '{"compensation": "10% standard commission rising to 20% on premium lines per the brand''s own affiliate newsletter, with an explicit ''no ceilings, caps, limitations or maximums'' statement on the official creator page.", "contact_access": "A named affiliate manager with a published email and weekly affiliate calls, plus a dedicated creator page \u2014 near top band per the rubric.", "credibility": "Bootstrapped brand operating since 2014 with 2+ million orders claimed on its own site and Leaping Bunny certification.", "niche_fit": "Natural skincare and self-tanner are core beauty UGC categories with highly visual before/after content.", "opportunity_availability": "Sign-up is pitched as a 60-second registration on the official page, open today.", "ugc_evidence": "An active, managed affiliate community with weekly meetups, campaign briefs and gifting for posts \u2014 though no paid campaigns and no published creator counts."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tiffen', 'https://tiffen.com', 'The Tiffen Company of Hauppauge, New York — a manufacturer of photographic filters and imaging accessories founded by Sol Tiffen in 1938, whose filters are made in its Long Island factory and whose brand family includes Steadicam camera stabilizers, Domke camera bags, Lowel lighting and Davis & Sanford tripods, sold to photographers, filmmakers and content creators.', 'United States', 'published') returning id into bid;
