  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://tiffen.com/pages/affiliate-program.', 'https://tiffen.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tiffen Affiliate Program', 'https://tiffen.com/pages/affiliate-program', 'https://tiffen.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tiffen.com/pages/affiliate-program', 'official_site', 'affiliate', 'Tiffen''s official affiliate page states: ''Earn 10% on any sales made using your referral'', ''FREE TO JOIN — Signing up is completely FREE and takes only a few minutes to register'', and under UNLIMITED EARNINGS: ''Refer as many people as you''d like with no cap on the commision you can earn.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Tiffen_(company)', 'listing', 'general', 'Wikipedia''s company profile places Tiffen in Hauppauge, New York, manufacturing filters for photography and professional film products, notes Academy Awards for technical achievements in filtration, and lists its owned brands: Steadicam, Domke, Lowel Light, Davis & Sanford, Listec, Stroboframe and Zing Designs.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tiffen.com/pages/our-story', 'listing', 'ugc_collab', 'Tiffen''s own About page describes 85+ years supplying the consumer/professional photography, motion picture and broadcast industries; the affiliate offer is a simple open referral page with no ambassador community, creator roster or published creator counts, so creator saturation is marked unknown rather than assumed low.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 18, 8, 13, 7, 8, 5, '{"compensation": "A flat 10% on any referred sale with an explicit ''no cap on the commission you can earn'' statement on the brand''s own page.", "contact_access": "A public join page only, with no published partnerships email \u2014 mid-range per the rubric.", "credibility": "An 85+ year-old manufacturer with Academy and Emmy technical awards and factories in New York, California and London.", "niche_fit": "Filters and camera accessories are staple gear for photography, film and travel creators \u2014 a partial lifestyle fit rather than a classic beauty/travel niche.", "opportunity_availability": "Free to join in minutes from the official page, open today.", "ugc_evidence": "A basic open affiliate program with referral tracking; no creator community, gifting or ambassador layer is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Annmarie Skin Care', 'https://shop.annmariegianni.com', 'Clean, wild-crafted skincare brand founded in 2009 by Annmarie and Kevin Gianni, selling herb-infused, MADE SAFE and Leaping Bunny certified skincare through its own store, with a Brand Ambassador program that pays commission on new customers referred by link or code.', null, 'published') returning id into bid;
