  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://shop.annmariegianni.com/pages/brand-ambassador', 'https://shop.annmariegianni.com/pages/brand-ambassador', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://shop.annmariegianni.com/pages/brand-ambassador.', 'https://shop.annmariegianni.com/pages/brand-ambassador', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Annmarie Skin Care Brand Ambassador Program', 'https://shop.annmariegianni.com/pages/brand-ambassador', 'https://shop.annmariegianni.com/pages/brand-ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.annmariegianni.com/pages/brand-ambassador', 'official_site', 'affiliate', 'Annmarie Skin Care''s official Brand Ambassador page publishes the full structure: 20% commission on the first order from every new customer referred, lifetime tiers rising to 25% at $2,500, 30% at $5,000 and 35% at $10,000+ in new-customer sales, monthly sales bonuses (5% at $500, 7% at $1,000 in a month), commissions held 60 days then paid monthly by PayPal or store credit with a 10% bonus. No fetched source states an earnings cap or its absence, so commission_cap is marked unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/p/DPzPnHAkl9P/', 'listing', 'ugc_collab', 'The brand''s own Instagram announcement (October 14, 2025) launches the Brand Ambassador Program as a brand-new program — ''Become a Brand Ambassador'' with tier graphics — direct evidence the creator program only recently opened and is still building its first ambassador base.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.annmariegianni.com/en-US/brand-ambassador-toolkit-2528943', 'official_site', 'contact', 'The brand''s Ambassador Toolkit support page confirms ambassadors start at 20% on qualifying first-time purchases and unlock tiers up to 35% plus monthly bonuses, and publishes the ambassador team contact route via the support portal.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 16, 12, 8, 4, '{"compensation": "20% starting commission on new-customer orders rising to 35% by lifetime tier, plus monthly bonuses \u2014 among the highest published rates in this batch \u2014 though no source states whether earnings are capped, so the cap is honestly unknown.", "contact_access": "A published program email (brandambassadors@annmariegianni.com) plus a full program page and support toolkit \u2014 near top band per the rubric.", "credibility": "Clean beauty brand operating since 2009 with MADE SAFE and Leaping Bunny certifications cited in its own launch materials.", "niche_fit": "Wild-crafted, ingredient-led skincare is a core clean-beauty UGC niche with a loyal audience.", "opportunity_availability": "Anyone can apply today; the brand also personally invites longtime customers.", "ugc_evidence": "A structured ambassador program with a portal, referral links/codes, tier progression and bonuses, launched in October 2025."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Beyond Pure Botanicals', 'https://beyondpurebotanicals.com', 'Faith-led botanical skincare brand founded by master herbalist Samantha Vickers, selling slow-crafted, whole-herb skincare made with nourishing oils and raw beeswax through its own website; a portion of every purchase supports Safe Haven Baby Boxes.', null, 'published') returning id into bid;
