  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://beyondpurebotanicals.com/pages/affiliate-program.', 'https://beyondpurebotanicals.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Beyond Pure Botanicals Affiliate Program', 'https://beyondpurebotanicals.com/pages/affiliate-program', 'https://beyondpurebotanicals.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beyondpurebotanicals.com/pages/affiliate-program', 'official_site', 'affiliate', 'Beyond Pure Botanicals'' official affiliate page publishes a seven-level tier table — 10% on $0-$499 monthly sales rising through 12%, 15%, 20% and 23% to 30% at $5,000+ — with a 14-day link window, no minimum payout, monthly payment by bank deposit or product credit, a $50 bonus when a recruited affiliate reaches $500 in sales, and applications handled through UpPromote. No fetched source states an earnings cap or its absence, so commission_cap is marked unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beyondpurebotanicals.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'The same page shows a tiny, founder-led operation: the product reviews displayed on the program page number just 10, and the affiliate community is small enough that partners are invited to help choose names for new products.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beyondpurebotanicals.com/pages/affiliate-program', 'official_site', 'general', 'The page tells founder Samantha Vickers'' story — a master herbalist who spent decades studying herbs — and describes formulas as slow-crafted with whole herbs, nourishing oils, pure ingredients and raw beeswax, with a portion of every purchase supporting Safe Haven Baby Boxes.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 14, 7, 8, 2, '{"compensation": "Published tiers from 10% up to 30% of monthly sales with no minimum payout \u2014 a strong rate ladder \u2014 but no source states the cap position, so it is marked unknown.", "contact_access": "An application route from the official program page (via UpPromote), but no published partnerships email \u2014 mid-range per the rubric.", "credibility": "Very small founder-led brand with a handful of public reviews and little independent coverage.", "niche_fit": "Botanical, whole-herb skincare fits the clean-beauty UGC niche, with a distinctive faith-led angle.", "opportunity_availability": "Free to join for anyone 18+ with an active online presence, open today.", "ugc_evidence": "A real tiered affiliate community with referral bonuses and product-input perks, run at micro scale."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('DreamTraveller', 'https://dreamtraveller.com', 'Direct-to-consumer luggage brand designing suitcases with aerospace-grade aluminum frames, ultra-light polycarbonate shells, quiet spinner wheels and smart front or top-opening designs, sold online in the United States under the tagline ''Travel Together. Grow Together.''', null, 'published') returning id into bid;
