  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://dreamtraveller.com/pages/affiliate', 'https://dreamtraveller.com/pages/affiliate', 'verified', now());
