  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'DreamTraveller Affiliate Program (BixGrow)', 'https://dreamtraveller.bixgrow.com', 'https://dreamtraveller.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dreamtraveller.com/pages/affiliate', 'official_site', 'affiliate', 'DreamTraveller''s official affiliate page runs sign-up through the BixGrow affiliate network, publishes affiliate@dreamtraveller.com for questions, and its FAQ confirms: no charge to participate, no minimum sales requirement, a 30-day cookie, and monthly payment once a month''s commission passes $25. Neither this page nor the BixGrow program page publishes a commission percentage or any statement about an earnings cap, so the rate is null and commission_cap is marked unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dreamtraveller.com/pages/affiliate', 'official_site', 'ugc_collab', 'The same page shows a new brand actively building its first creator base: it invites fashion, lifestyle and family creators to ''capture authentic travel moments'', says ''We''re looking for fresh voices to review our products'', and offers to send products to test for review.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dreamtraveller.com/pages/affiliate', 'official_site', 'general', 'The page describes the product line — aerospace-grade aluminum frames, ultra-light unbreakable polycarbonate shells, whisper-quiet spinner wheels and front/top-opening designs — and notes the brand currently ships only within the United States and focuses on partners with US audiences.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 6, 11, 8, 3, '{"compensation": "No commission percentage or cap position is published on either fetched program page, so this stays low per the rubric despite the program being live.", "contact_access": "A published affiliate email plus application pages on both the brand site and its BixGrow portal \u2014 near top band per the rubric.", "credibility": "New direct-to-consumer luggage brand with US-only shipping and limited independent coverage so far.", "niche_fit": "Luggage is core travel-creator content \u2014 packing, airport and review formats \u2014 and the brand explicitly targets fashion, lifestyle and family creators.", "opportunity_availability": "Applications are open now with no joining fee and no minimum sales requirement; approval is reviewed within a few working days.", "ugc_evidence": "An open affiliate program with product seeding for reviews, explicitly recruiting its first wave of creator voices."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ivy City Co', 'https://ivycityco.com/', 'Utah-based US women''s and children''s dress brand founded in 2015 by three women, known for unique, modest ''mommy and me'' dresses in 20+ sizes including maternity and curve. Its Ivy Ambassador program pays a flat 15% commission via ShopMy, with free-product opportunities through challenge cycles.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'ivycityco', 'https://www.instagram.com/ivycityco/');
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'tiktok', 'ivycityco', 'https://www.tiktok.com/@ivycityco');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'hello@ivycityco.com', 'https://ivycityco.com/pages/ivy-ambassador-program', 'https://www.cpsc.gov/Recalls/2025/Ivy-City-Recalls-Childrens-Pajamas-Due-to-Burn-Hazard-Violation-of-Federal-Flammability-Regulations-Sold-Exclusively-by-Ivy-City?utm_campaign&utm_content&utm_medium=email&utm_source=govdelivery&utm_term=20250117', 'needs_review', null);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://ivycityco.com/pages/collab', 'https://ivycityco.com/pages/collab', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShopMy (commission via ShopMy per official ambassador terms; applications also via TYB per official terms/Instagram announcement)', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ivycityco.com/pages/ivy-ambassador-program.', 'https://ivycityco.com/pages/ivy-ambassador-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ivy Ambassador Program / Ivy Icon Affiliate Program (Collabs)', 'https://ivycityco.com/pages/collab', 'https://ivycityco.com/pages/collab', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ivycityco.com/pages/ivy-ambassador-program', 'official_site', 'compensation', 'Official Ivy Ambassador Program page: ambassadors get ''exclusive access, free product opportunities, and a commission on every sale you inspire'' via challenge cycles; terms state ''Commission terms: Flat 15% commission rate via ShopMy, subject to ShopMy''s standard payout schedule'', plus TYB coin discounts/leveling, earn-first gifting, and a public Instagram/TikTok requirement; brand reserves usage rights to ambassador content in paid ads, organic social, email and web. COMMISSION_CAP: no cap wording was found on this page or the Collabs page — no ''no cap''/''unlimited'' statement — so commission_cap is unknown. CONFLICT noted: older third-party listings report lower rates (AffJumbo 8.4%, Shopper.com 5-10%), which conflict with the current official 15%; the official 15% is used.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ivycityco.com/pages/collab', 'official_site', 'affiliate', 'Official Collabs page: ''Our Ivy Icon Affiliate Program is a community of moms, fashionistas, trendsetters and Ivy City Co. enthusiasts from all backgrounds and audience sizes. Creators who join our community receive fun perks and incentives in exchange for their support on social... please apply below and our team will review your application!'' Partnership opportunities listed: affiliate marketing, campaigns, content creation, additional opportunities.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/p/Dcb-pTQIBBg/', 'listing', 'ugc_collab', 'CREATOR_SATURATION: UNKNOWN. A fetched Ivy City Instagram post (verified @ivycityco, 930K followers) announces ''AMBASSADOR APPLICATIONS are open'', listing 15% commission, TYB coins, free product opportunities, no minimum follower count, and application via TYB — showing an actively recruiting program, but it gives no total creator or sponsored-post count for the last 12 months/30 days. Beacons Universe brand page was attempted but returned 429 and CollabFeed searches returned no Ivy City Co brand counts, so saturation cannot be marked low/medium/high on evidence.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cpsc.gov/Recalls/2025/Ivy-City-Recalls-Childrens-Pajamas-Due-to-Burn-Hazard-Violation-of-Federal-Flammability-Regulations-Sold-Exclusively-by-Ivy-City?utm_campaign&utm_content&utm_medium=email&utm_source=govdelivery&utm_term=20250117', 'listing', 'contact', 'US CPSC recall notice lists Ivy City Co. of Riverton, Utah, consumer contact email hello@ivycityco.com and site https://ivycityco.com/ — supports US country and the published contact email; the brand''s own accessibility page search result also lists hello@ivycityco.com (that page''s direct fetch returned 429, so the CPSC/government source is cited).', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 15, 14, 9, 5, '{"compensation": "Published flat 15% on the official ambassador page = 15 per calibration; older 8.4%/5-10% third-party listings conflict and are noted; no uncapped wording found.", "contact_access": "Own-site ambassador and Collabs application pages, plus a published contact email = 14.", "credibility": "Established verified brand founded 2015 in Utah, 930K Instagram followers on fetched posts = 5.", "niche_fit": "Core women''s dresses / mommy-and-me fashion \u2014 strong UGC fit, narrower category than a general boutique = 28.", "opportunity_availability": "Publicly open ambassador applications with no minimum follower count reported, team-reviewed = 9.", "ugc_evidence": "Two named open programs (Ivy Ambassadors and Ivy Icon Affiliate) with documented challenge cycles, content-usage terms and active application announcements = 18."}'::jsonb);
