  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://pinklily.com/pages/pink-lily-ambassador-program.', 'https://pinklily.com/pages/pink-lily-ambassador-program', 'needs_review', now());
