  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pinklily.com/pages/pink-lily-ambassador-program', 'official_site', 'affiliate', 'Official Ambassador Program page: minimum 10k followers, public accounts, US citizen, 18+; perks include ''10% commission, with opportunities to level up and earn more''. COMMISSION_CAP: no cap wording was found on this page or the affiliate page — no ''no cap'', ''unlimited earnings'' or ''no limit'' statement — so commission_cap is unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pinklily.com/pages/affiliate-program', 'official_site', 'compensation', 'Official Affiliate Program page for creators under 10K followers, based in the US, over 18: ''10% commission on all orders made from your commissionable link''. This confirms the 10% rate independently of the ambassador page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.latestnigeriannews.com/p/612993/how-to-start-an-online-fashion-store-from-a-kentucky-couple-whose-side-hustle-be.html', 'listing', 'ugc_collab', 'CREATOR_SATURATION: HIGH. Article republishing a CNBC profile states ''A 620-member ambassador program'' — ambassadors earn 10% on every sale, the program has 620 members, generated $7.4 million in sales in the past year, and ''thousands of people apply''. A 620-member active ambassador roster is high saturation for a boutique. Beacons Universe brand page was attempted but returned 429 and CollabFeed gave no brand count, so this 620-member figure is the saturation evidence used. Note the underlying profile is older (2022-era), so the count is not a last-30-days figure.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nz.trustpilot.com/review/pinklily.com?page=3', 'listing', 'contact', 'Trustpilot company details list Pink Lily at 472 Century St, 42101, Bowling Green, United States, contact email help@pinklily.com, website pinklily.com — supports US country and the published contact email.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 30, 18, 12, 14, 9, 5, '{"compensation": "Published 10% on both official ambassador and affiliate pages = 12 per calibration; no uncapped wording found, so no uncapped credit.", "contact_access": "Own-site ambassador and affiliate program pages with application routes = 14.", "credibility": "Established verified brand, 1.7M Instagram followers on fetched posts, Bowling Green KY address on Trustpilot = 5.", "niche_fit": "Core US women''s fashion boutique, everyday/try-on content = 30.", "opportunity_availability": "Affiliate route is publicly open to smaller US creators under 10K; ambassador tier is selective (10K+, thousands apply) = 9 for the open affiliate route.", "ugc_evidence": "Named open ambassador + affiliate programs with documented activity: 620 members and $7.4M in ambassador sales reported = 18."}'::jsonb);
