  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Shopper.com/partnerships/bombshellsportswear-com-affiliate-program', 'affiliate_network', 'compensation', 'Shopper lists 5-10% payout per sale. InfluencerRate (https://www.influencerrate.com/affiliate-program/bombshellsportswear) conflicts, claiming up to 15% with 30-day cookie — rates conflict honestly noted, 10% used as the Shopper range top. COMMISSION_CAP: No cap wording was found on any fetched page — no ''no cap'', ''unlimited earnings'', or earnings-limit FAQ — so commission_cap is unknown, not uncapped.', 'publicly_reported', now());
