  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.constantlyvariedgear.com/pages/affiliate-program-terms-conditions', 'official_site', 'compensation', 'COMMISSION_CAP: No cap wording was found — the official terms contain no ''no cap'', ''unlimited earnings'' or earnings-limit statement, so commission_cap is unknown. COMMISSION RATE: not published — the terms only say ''Commission rates are subject to change at Constantly Varied Gear''s discretion''; a StoreProfiles listing independently notes CVG on Social Snowball with ''terms not published'', so commission_rate is null.', 'verified', now());
