  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 30, 16, 4, 14, 9, 5, '{"compensation": "Commission is confirmed to exist (discount code for followers plus commission on sales) but no rate is published anywhere fetched, and no uncapped wording was found, so only unpublished-rate credit applies.", "contact_access": "Own-site application route via the brand''s official help center article with an apply link, plus full published affiliate terms on the brand''s own store.", "credibility": "Established verified brand: founded 2013, A-rated BBB profile, $10M-$25M estimated revenue in directory listings, large owned community and podcast.", "niche_fit": "Perfect core fitness UGC fit: women''s training apparel (squat-proof leggings, bras, shorts) built around a women''s fitness community.", "opportunity_availability": "Publicly open application linked from the brand''s own help center; applications are reviewed but anyone can apply.", "ugc_evidence": "Named open Brand Ambassador Program with documented commission and UGC rights terms, plus verified (if very sparse) creator posts on Beacons Universe."}'::jsonb);
