  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/showpo-us-affiliate-program/', 'affiliate_network', 'compensation', 'FlexOffers listing (updated Jul 31, 2026): payout ranges 1.6%-8% depending on customer status, sale flag and coupon used; 30-day cookie. Conflicting published rates noted: AffJumbo lists 3.2%, Shopper lists 1.6-8%. COMMISSION_CAP finding: no cap wording was found on any fetched Showpo page — no ''no cap'', ''unlimited earnings'' or ''no limit'' statement, so commission_cap is unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.netinfluencer.com/showpo-influencer-program/', 'listing', 'ugc_collab', 'NetInfluencer describes a Showpo Influencer Program for fashion/lifestyle creators with 50%+ female audience, contacted by email pitch (email redacted in fetched snippet, so not recorded here). No own-site application form was found; affiliate joining is via networks including FlexOffers, Commission Factory and Rakuten per affi.io listing.', 'publicly_reported', now());
