  insert into public.brands (name, website, description, country, status) values ('VICI', 'https://www.vicicollection.com', 'US women''s fashion brand (VICI Collection), founded in 2012 and headquartered in Concord, California, selling trendy, affordable women''s clothing, accessories and shoes for any life stage. It runs an affiliate program via Impact, Skimlinks and LTK, and a brand ambassador program reported at 5% commission.', 'United States', 'published') returning id into bid;
