  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact (Impact Radius), also Skimlinks and RewardStyle/LTK per official FAQ', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.vicicollection.com/pages/affiliate-faq.', 'https://www.vicicollection.com/pages/affiliate-faq', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'VICI Affiliate Program (Impact / Skimlinks / LTK) and VICI Brand Ambassador Program', 'https://www.vicicollection.com/pages/affiliate-faq', 'https://www.vicicollection.com/pages/affiliate-faq', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vicicollection.com/pages/affiliate-faq', 'official_site', 'affiliate', 'Official VICI Affiliate FAQ: ''We''re also on Skimlinks and RewardStyle/LTK. Just find VICI on those platforms to join'' (in addition to Impact Radius/Impact); joining is FREE; commission is earned on a purchase within 15 days of clicking the affiliate link and paid monthly via the affiliate provider dashboard. No commission percentage and no cap wording appear on this page. COMMISSION_CAP: no ''no cap''/''unlimited earnings''/''no limit'' wording was found on any fetched VICI source, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.netinfluencer.com/vici-collection-influencer-program/', 'creator_report', 'compensation', 'NetInfluencer''s program guide, reporting the VICI website''s ambassador terms: requirements minimum 5,000 followers, fashion/lifestyle feeds, public Instagram, based in the United States, over 18; perks ''40% discount on VICI purchases, up to $350'', ''20% Off Personalized Link'', ''5% Commission on purchases using your code'', early access; monthly campaigns requiring 1 video, 3 Instagram carousels and 3 stories. CONFLICT noted: Yazing lists VICI Collection at ''Up to 4% of Sales'' (https://yazing.com/brand-ambassador-programs/vicicollection-influencer), so published rates conflict — 5% ambassador (reported from brand site) vs up to 4% via Yazing. The 5% ambassador rate is used as the headline rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.netinfluencer.com/vici-collection-influencer-program/', 'creator_report', 'ugc_collab', 'CREATOR_SATURATION: UNKNOWN. NetInfluencer documents multiple named influencer collaborations and ambassador content shared on VICI''s official TikTok/Instagram (e.g. Rachel Proctor, Emily Herren Travis, Kelsey Bresinger, Carla Nunez, Jenn Jackson), showing real creator activity, but gives no total creator or sponsored-post count for the last 12 months/30 days. Beacons Universe brand page was attempted but returned 429 and CollabFeed searches returned no VICI brand counts, so saturation cannot be marked low/medium/high on evidence.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.netinfluencer.com/vici-collection-influencer-program/', 'creator_report', 'general', 'VICI Collection founded in 2012 by Sandra Sayegh Dudum, headquartered in Concord, California, over 150 team members, mission to ''make on-trend styles accessible and affordable for women at any life stage'' per its website; fetched Instagram posts show @vici as a verified author with 1.9M followers. No published contact email was found on any fetched VICI page, so contacts email is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 30, 16, 9, 9, 7, 5, '{"compensation": "Published 5% ambassador commission = 9 per calibration; conflicting up-to-4% Yazing listing noted, and no uncapped wording found.", "contact_access": "No own-site application form or published email found; joining is network-only via Impact/Skimlinks/LTK from the official FAQ = 9.", "credibility": "Established verified brand founded 2012, 1.9M Instagram followers, Nordstrom partnership reported = 5.", "niche_fit": "Core US women''s fashion boutique across clothing, shoes and accessories = 30.", "opportunity_availability": "Affiliate joining is publicly described on the official FAQ via networks, but approval is required and the ambassador route is sign-in/selection based = 7.", "ugc_evidence": "Named ambassador program with documented monthly campaigns, posting requirements and multiple named influencer collaborations = 16."}'::jsonb);
