  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bornprimitive.com/pages/ambassador-app', 'official_site', 'affiliate', 'Official Born Primitive Brand Ambassador Application page exists but currently states: ''At this time, we have closed our application to the program.'' The separate Ambassador Testimonials page says creators ''have been hand-selected by our team'', indicating a selection-based program.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://whopaysinfluencers.com/brand/born-primitive/', 'listing', 'affiliate', 'WhoPaysInfluencers (checked Oct 2026) lists the Born Primitive Brand Ambassador Program as ''Open application'' with 6 people on record, 4 brand-confirmed (Blake Cook, Jenay DeCaussin, Katie Knight, Kirt Finnell), plus 2 creators with sponsored posts. This conflicts with the brand''s own page, which currently shows applications closed.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bornprimitive.com/pages/ambassador-app', 'official_site', 'compensation', 'COMMISSION_CAP: No cap wording was found — no fetched Born Primitive page states ''no cap'', ''unlimited earnings'' or any earnings-limit answer, so commission_cap is unknown. COMMISSION RATE: not published (WhoPaysInfluencers also lists pay as ''Not published''). Note: a page at bornprimitives.us.com advertising ''up to 10%'' describes shoes (''cushiest, comfiest, airiest, featheriest, and lightest shoes on Earth'') — that is the Born Shoes brand, NOT Born Primitive fitness, so its 10% rate was excluded.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/born-primitive', 'listing', 'ugc_collab', 'CREATOR_SATURATION: Beacons Universe (updated Nov 12, 2026) shows 50 creators all time, 26 public posts in the last 12 months, 4 creators / 8 mentions in the 30 days to Nov 20, 2026, and only 1 sponsored post in the last 12 months (@rebelredeemed316, Oct 5, 2026). Sponsored saturation is very low but total creator mentions are moderate, so saturation is rated medium.', 'verified', now());
