  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 4, 10, 3, 5, '{"compensation": "No commission rate published on any verified Born Primitive source; the only 10% figure found belongs to Born Shoes, a different brand, so it earns no rate credit. No uncapped wording found.", "contact_access": "Own-site ambassador application page plus a published contact email, but the application is currently closed, reducing access below a live own-site form.", "credibility": "Established verified brand: founded 2014, 51-500 employees per Beacons, 9-figure business per its own About page, Virginia Beach HQ.", "niche_fit": "Core fitness fit: athlete-tested training apparel and footwear for men and women, CrossFit/tactical roots.", "opportunity_availability": "Application page exists but states applications are closed; program appears hand-selected, so availability is pitch/selection-level only right now.", "ugc_evidence": "Named Brand Ambassador Program with 4 brand-confirmed ambassadors and documented sponsored creator posts on Beacons/WhoPaysInfluencers, but terms are unpublished and applications are closed."}'::jsonb);
