  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 9, 11, 8, 3, '{"compensation": "Published payout is a modest 5-10% range (10% recorded as the top of the range); cap unknown.", "contact_access": "Two published brand emails (hey@wearerasa.com, hello@wearerasa.com) plus an instant-approval affiliate route via Shopper.com.", "credibility": "Brand facts are verified on its own site, but the commission listing is a partly templated Shopper.com page, so terms need re-confirmation.", "niche_fit": "Adaptogen morning-routine and coffee-swap content is a strong wellness UGC demo niche.", "opportunity_availability": "Shopper.com advertises instant approval for the Rasa affiliate program, so signup appears open now.", "ugc_evidence": "33 creators have posted about Rasa on Beacons Universe, showing real creator activity at small scale, with none in the last 30 days."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Buoy', 'https://justaddbuoy.com/', 'Buoy makes unflavored liquid electrolyte drops and sea salt with ocean electrolytes and 87+ trace minerals, with no sugar, sweeteners or flavors, designed to be added to any drink. Its site says the formulas are clinically proven to hydrate 64% better than water alone and offers a Chronic Illness Support Program with 35% off for life for people living with chronic illness.', 'United States', 'published') returning id into bid;
