  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://justaddbuoy.com/policies/terms-of-service', 'official_site', 'affiliate', 'Official Buoy Affiliate Program Terms (last updated September 21, 2026): ''The self-serve Affiliate Program... is the commission-based program administered through our affiliate platform, Superfiliate'' and ''Your Commission rate is displayed in your affiliate dashboard'' — no rate and no cap/unlimited wording is published in the terms; commissions are earned on first orders only. Cap verdict: no fetched page says ''no cap'', ''unlimited earnings'' or ''no limit on how much you can earn'', so commission_cap is unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/buoy-hydration/', 'affiliate_network', 'compensation', 'Lasso listing: Buoy Hydration commission rate ''Up to 22.5%'', cookie duration 14 days, affiliate network Lasso, payout threshold $10, approval requirements none.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.socialsnowball.io/post/buoy-affiliate-marketing-case-study', 'listing', 'compensation', 'Social Snowball case study on Buoy''s affiliate operations: ''Entry-level affiliates start at 20%. Top performers can earn up to 35%. Movement through tiers is based on real sales milestones'' and affiliates get a free welcome gift and early access to launches. Base rate used here is 20%.', 'publicly_reported', now());
