  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 15, 12, 8, 5, '{"compensation": "Published 20% entry rate rising to 35% for top performers per Social Snowball, and up to 22.5% per Lasso; cap is unknown because no fetched page states uncapped wording.", "contact_access": "Published general email hello@justaddbuoy.com on the official terms/privacy pages plus a full official affiliate terms page; no dedicated affiliate email or public signup URL was fetched.", "credibility": "Detailed official affiliate terms dated September 2026, clinically-proven hydration claims and a medical board / 900+ clinician recommendations cited on its own product pages.", "niche_fit": "Squeeze-into-any-drink hydration drops are an easy UGC demo, with strong chronic-illness, POTS and everyday-wellness angles for women creators.", "opportunity_availability": "Self-serve affiliate program is described as live in the official terms, but no direct public application URL was returned by search, so signup is via the Superfiliate platform after application.", "ugc_evidence": "Documented affiliate case study ($400K in 12 months via streamlined affiliate operations), tiered creator commissions, gifting and creator affiliate posts on Instagram."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tailwind Nutrition', 'https://www.tailwindnutrition.com/', 'Tailwind Nutrition, owned, operated and manufactured in Durango, Colorado since 2012, makes all-natural endurance sports nutrition drink mixes that are free of GMOs, dairy, soy and gluten and are designed to be easy to digest. Its lines include Endurance Fuel, Recovery Mix and Rapid Hydration for fueling and recovery during and after exercise.', 'United States', 'published') returning id into bid;
