  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yazing.com/affiliate-programs/tailwind-nutrition-affiliate-program', 'affiliate_network', 'compensation', 'Yazing''s Tailwind Nutrition-specific listing (not the Tailwind Pinterest app, whose separate 15% listings were excluded): ''Tailwind Nutrition Commission Rate Details: Yazing members earn 2% of Sales.'' This is the only nutrition-brand-specific published rate found.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://supportcrew.tailwindnutrition.com/support/solutions/articles/24000083364-tailwind-ambassador-trailblazer-program', 'official_site', 'ugc_collab', 'Official Tailwind Nutrition support article for the Tailwind Ambassador (Trailblazer) Program: ''We are so stoked that you are interested in getting involved with us! Send us a message via our contact page.'' The brand''s Instagram also promoted ''AMBASSADOR APPLICATIONS ARE OPEN!'' for the Trailblazer program in January 2025. No creator-count evidence was fetched, so creator_saturation is unknown.', 'verified', now());
