  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 6, 9, 6, 4, '{"compensation": "Only nutrition-specific published rate found is 2% via Yazing; the official Trailblazer/AvantLink pages publish no rate and no cap wording, so cap is unknown.", "contact_access": "Published support email and an official support/contact route for the ambassador program; no dedicated affiliate email was fetched.", "credibility": "Established since 2012, manufactures in Durango, CO, sold in run/bike/outdoor stores nationwide and 37 countries, with a named athlete team.", "niche_fit": "Endurance fuel and hydration mixes demo well in training/race-day UGC, but the audience is narrower endurance sports rather than broad women''s wellness.", "opportunity_availability": "AvantLink program and Trailblazer ambassador route exist, but the official ambassador article is dated January 2023 and directs applicants to a contact page rather than an open signup form.", "ugc_evidence": "Trailblazer ambassador recruitment posts, athlete-team content and creator brand mentions on Beacons Universe creator pages; no sponsored-post or creator counts for the brand itself were fetched."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FullWell', 'https://fullwellfertility.com/', 'FullWell offers dietitian-formulated supplements designed to support fertility, pregnancy and overall wellness, including prenatals and fertility formulas for women and men. It was founded by registered dietitian and fertility expert Ayla Barmmer, and a 2026 review notes it third-party tests every lot for contaminants and publishes the results.', 'United States', 'published') returning id into bid;
