  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Katalys', 25, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.glp1drugs.org/l/fullwell-fertility-review.', 'https://fullwellfertility.com/pages/become-an-ambassador', 'needs_review', now());
