  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fullwellfertility.com/pages/become-an-ambassador', 'official_site', 'affiliate', 'Official FullWell Ambassador Program page: ambassadors receive ''personalized affiliate links to earn a commission'' and ''Earn a generous commission on every first-time order placed through your unique ambassador link. Plus, earn elevated commissions during our exclusive promotional periods.'' Application is via an ''Apply Here'' link to Roster (apply.getroster.com). No percentage and no cap/unlimited wording is published on the page, and questions go to hello@fullwellfertility.com; the program is framed for health practitioners.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.glp1drugs.org/l/fullwell-fertility-review', 'listing', 'compensation', 'Published review with affiliate disclosure ''we earn 25% on orders placed through this page'' and source line: ''Katalys offer listing #1461, retrieved 11 August 2026 — 25.00% commission, United States targeting, sub-network Impact.'' The ''Un'' in the search snippet was ''United States'', not uncapped — no cap wording was found, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/fullwell/', 'affiliate_network', 'compensation', 'Lasso listing reports a lower figure, ''Up to 15.0%'' commission with a 14-day cookie, for FullWell''s dietitian-formulated fertility, pregnancy and wellness supplements — noted here as a conflicting published rate versus the 25% Katalys rate used in the affiliate field.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.thegoodtrade.com/features/organic-prenatal-vitamins/', 'listing', 'general', 'The Good Trade prenatal roundup: FullWell is American made, third-party tested, woman owned, developed by a registered dietitian and fertility expert, $50 for a 30-day supply. No creator-count/saturation evidence was fetched, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 15, 13, 7, 5, '{"compensation": "25% reported via the Katalys listing in a published review, a high rate, but Lasso reports up to 15% and no fetched page states uncapped wording, so cap is unknown.", "contact_access": "Published email hello@fullwellfertility.com on the official ambassador page plus a direct ambassador application page.", "credibility": "Clinician/RDN-founded, per-lot third-party contaminant testing with published results and complete supplement facts, per the fetched 2026 review.", "niche_fit": "Fertility, preconception and pregnancy supplements are a strong, high-intent UGC demo niche for women creators, with clear routine and journey content angles.", "opportunity_availability": "Ambassador application is open via the official page/Roster, but the program is explicitly framed for health practitioners, which narrows general UGC creator access.", "ugc_evidence": "Active practitioner ambassador community, a practitioner directory and regular educational Instagram content; no open UGC brief or creator counts were fetched."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Spark Paws', 'https://www.sparkpaws.com', 'Spark Paws is a pet supplies and retail apparel company based in Richmond Hill, Canada. Beacons Universe summarises its offer as: ''We make premium pet products both the human and dog will love. Discover quality dog apparel, collars, chains, shoes, owner matching set, accessories and more.'' Its Creator Club pays creators a share of Meta ad spend running their videos, alongside TikTok Shop and Social Snowball affiliate sales.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'ambassador@sparkpaws.com', 'https://www.sparkpaws.com/pages/brand-ambassador-affiliate-sign-up', 'https://www.sparkpaws.com/pages/dog-model-ambassador-terms-conditions', 'verified', now());
