  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 6, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.sparkpaws.com/pages/creator-club.', 'https://www.sparkpaws.com/pages/brand-ambassador-affiliate-sign-up', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Spark Paws Brand Ambassador Affiliate Sign Up / Creator Club (6% of Meta ad spend, no cap)', 'https://www.sparkpaws.com/pages/brand-ambassador-affiliate-sign-up', 'https://www.sparkpaws.com/pages/creator-club', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sparkpaws.com/pages/creator-club', 'official_site', 'compensation', 'Cap language quoted from the fetched Creator Club page: ''What you earn - 6% of what we spend on Meta ads (Facebook and Instagram) running your videos. - No cap. It keeps paying for as long as the ads run.'' This is explicit uncapped wording, so commission_cap is marked uncapped. Note the 6% is a share of ad spend, not a per-sale rate; the page also says TikTok Shop sales earn commission and Social Snowball affiliate sales are paid as usual.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/spark-paws', 'listing', 'ugc_collab', 'Saturation evidence is conflicting, so creator_saturation is marked unknown, not low. The fetched Creator Club page says ''Invitation only'', ''You''re one of a small group of creators we''ve invited'' and ''The Club is a small, exclusive group of creators we trust'' - which points to a small program. However Beacons Universe (fetched) lists 136 creators who have posted about Spark Paws all time, 339 public posts in the last 12 months and 32 sponsored posts in the last 12 months, which is not low overall brand saturation.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sparkpaws.com/pages/creator-club', 'official_site', 'affiliate', 'Creator Club is invitation-only and pays monthly by PayPal in USD within 10 days after month end, balances under $25 roll over. A separate public Brand Ambassador Affiliate Sign Up page exists on sparkpaws.com, giving a joinable route today, and the Dog Model Program terms (ambassador@sparkpaws.com) describe an application-based model program receiving product and commissions via a unique affiliate link.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/spark-paws', 'listing', 'general', 'Beacons Universe (fetched) describes Spark Paws as a pet supplies and retail apparel company based in Richmond Hill, Canada, 1-50 employees, with premium dog apparel, collars, chains, shoes and owner matching sets. The Creator Club page instructs creators to tag @sparkpawsofficial and use #SparkPawsCreator; no verified social profile URL was fetched, so socials are left empty rather than constructed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 12, 20, 12, 7, 5, '{"compensation": "Only candidate in the pool with explicit fetched uncapped wording (''No cap'') on its own program page; 6% of Meta ad spend plus TikTok Shop / Social Snowball sales commission.", "contact_access": "Public ambassador affiliate sign-up page plus a published ambassador email in the Dog Model terms; Creator Club itself is invitation-only, which limits direct access.", "credibility": "All key terms come from Spark Paws'' own fetched Creator Club page, cross-checked against Beacons Universe.", "niche_fit": "Pure pets brand - premium dog apparel, shoes, collars and matching owner sets, ideal for dog UGC.", "opportunity_availability": "Ambassador affiliate sign-up is public and joinable today; the uncapped Creator Club is invitation-only, so availability is partial.", "ugc_evidence": "Strong UGC mechanics (creator videos run as Meta ads, 90-day post requirement), but saturation is marked unknown: Beacons shows 136 creators and 32 sponsored posts in 12 months despite the small invited Club."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tuft + Paw', 'https://www.tuftandpaw.com', 'Tuft + Paw (branded Tuft & Paw on its own site) is an animals and pet supplies brand based in Vancouver, Canada, and a fast-growing retailer of modern cat furniture and accessories. Its own affiliates page says its mission is to provide beautiful, well-made furniture for cats while serving the homeless and foster cat community and advocating for no-kill shelters.', 'Canada', 'published') returning id into bid;
