  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 12, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.tuftandpaw.com/pages/affiliates.', 'https://www.tuftandpaw.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tuft + Paw Affiliate Program - 12% on all sales via ShareASale', 'https://www.tuftandpaw.com/pages/affiliates', 'https://www.tuftandpaw.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tuftandpaw.com/pages/affiliates', 'official_site', 'compensation', 'No cap language was found on the fetched official affiliates page. The page states ''12% commission on all sales (best payout in our industry)'', ''60 cookie days'' and ''Free to join'', with no wording such as ''no cap'', ''unlimited earnings'' or ''no limit on how much you can earn'', so commission_cap is marked unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/tuft-paw', 'listing', 'ugc_collab', 'Low saturation evidence from Beacons Universe (fetched): Tuft and Paw has posts from only 80 creators all time, 69 public posts in the last 12 months and only 3 sponsored posts in the last 12 months (most recently Roman, Oct 30, 2026). That is low relative to the other candidates in this pool (e.g. Earth Rated 277 creators / 31 sponsored, Tractive 162 / 22), so creator_saturation is marked low.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tuftandpaw.com/pages/affiliates', 'official_site', 'affiliate', 'Official affiliates page (fetched): 12% commission on all sales, 60 cookie days, free to join, real-time reporting. ''We have partnered with ShareSale.com. Your site will be reviewed for approval to join ShareASale and the Tuft and Paw affiliate program.'' Contact email published on the page: affiliate@tuftandpaw.com. A separate Awin listing found in search also mentions a 12% program, so the current network should be confirmed at signup.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/tuft-paw', 'listing', 'general', 'Beacons Universe (fetched) lists Tuft and Paw as an animals & pet supplies brand based in Vancouver, Canada, 1-50 employees, official website tuftandpaw.com. No verified social profile URL was fetched, so socials are left empty rather than constructed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 12, 13, 9, 5, '{"compensation": "Solid published 12% on all sales with a 60-day cookie from the brand''s own page, but no uncapped language was found, so cap is unknown and this scores below a verified uncapped program.", "contact_access": "Official affiliates page with a direct signup link and a published affiliate email (affiliate@tuftandpaw.com).", "credibility": "Rate, cookie and network all from the brand''s own fetched affiliates page, corroborated by Beacons and network listings.", "niche_fit": "Pure pets, cat-specific - modern cat furniture and litter, a clear niche for cat-owner UGC; narrower than dog brands because it is cat-only.", "opportunity_availability": "Free to join today via ShareASale signup linked from the official page, subject to site review.", "ugc_evidence": "Low saturation verified on Beacons: 80 creators all time and only 3 sponsored posts in the last 12 months."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Satechi', 'https://satechi.com', 'Satechi is a consumer electronics accessories brand founded in San Diego in 2005 by two college friends, Brock and Alan. It makes eco-premium tech accessories including wireless chargers, USB-C hubs, docking stations, keyboards and cables, designed primarily for Apple and PC setups.', 'United States', 'published') returning id into bid;
