  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Satechi Affiliate Program via ShareASale - 10% per sale', 'https://getlasso.co/affiliate/satechi/', 'https://getlasso.co/affiliate/satechi/', 'unverified', 'ugc');
