  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/satechi/', 'listing', 'compensation', 'No cap language was found on the fetched program listing: no wording such as ''no cap'', ''unlimited earnings'', ''no limit on how much you can earn'', and no FAQ answering an earnings-limit question. Commission cap is therefore recorded as unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/brands/satechi', 'listing', 'ugc_collab', 'Saturation evidence for LOW: CollabFeed page fetched in full states ''Satechi runs creator campaigns on Instagram (1 posts)'', ''CollabFeed has tracked 1 paid partnership post for Satechi'', and benchmarks are ''Based on 1 tracked partnership'' (data updated Apr 2026). SponsorRadar search result corroborates small scale: ''5 sponsored videos from Satechi across 5 YouTube creators''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://satechi.com/pages/about-us', 'official_site', 'general', 'Official About Us page fetched in full: ''San Diego, 2005. Two college friends, Brock and Alan, had a simple idea: create tech accessories that work great, look great, and improve people''s lives'' and ''We create eco-premium tech accessories that make everyday setups better''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 12, 8, 9, 5, '{"compensation": "Published 10% per sale on Lasso listing, but no uncapped language was found, so cap is unknown and compensation is scored below a verified uncapped program.", "contact_access": "Join route is public via the Lasso listing''s ShareASale join link, but CollabFeed states ''We do not have a verified partnership email for Satechi yet'', so no direct creator contact was verified.", "credibility": "Established brand founded in San Diego in 2005 per its own About Us page, with a live affiliate listing and tracked paid partnerships.", "niche_fit": "Core technology accessories and charging brand: chargers, hubs, docking stations and cables for Apple/PC setups, exactly the batch category.", "opportunity_availability": "Affiliate program is joinable today through the public ShareASale join link on the fetched listing.", "ugc_evidence": "Low saturation is evidenced, not assumed: CollabFeed tracked only 1 paid partnership post and SponsorRadar only 5 YouTube creators / 5 deals."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Native Union', 'https://www.nativeunion.com', 'Native Union is a design-led tech accessories brand founded in 2009 by Igor Duc and John Brunner, who met in Hong Kong. It creates premium charging cables, wireless chargers, cases and carry accessories combining thoughtful design, premium materials and sustainability, designed between Paris and Hong Kong.', 'Hong Kong', 'published') returning id into bid;
