  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Native Union Creator Affiliate Program - 10% commission', 'https://www.nativeunion.com/en-hk/pages/collab', 'https://www.nativeunion.com/en-hk/pages/collab', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nativeunion.com/en-hk/pages/collab', 'official_site', 'affiliate', 'Official Creator Affiliate Program page fetched in full: ''We''re inviting creators who share our values to join our affiliate program'' and ''You''ll receive: A personal promo code to offer your audience 15% off; 10% commission on every sale through your link or code; A welcome gift of your choice after your first sale''. The page also inconsistently says ''On top of your 15% commission'' in its gifts section; the explicit bullet rate of 10% is recorded. Creators on Instagram, TikTok, YouTube or blogs in tech, lifestyle, fashion, travel or design are invited.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nativeunion.com/en-hk/pages/collab', 'official_site', 'compensation', 'No cap language was found on the fetched official program page: no wording such as ''no cap'', ''unlimited earnings'', ''no limit on how much you can earn'', and no FAQ answering an earnings-limit question. The page says only ''the more you share, the more you earn'', which is not an explicit uncapped statement, so commission cap is recorded as unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/pr-emails/native-union', 'creator_report', 'ugc_collab', 'Saturation evidence for LOW: Snippet''s Native Union page, checked November 14, 2026, states ''Native Union lists no creator route'' and ''Native Union does not list an influencer, ambassador or affiliate program on the pages we checked on November 14, 2026'', indicating the creator program is new/small. The brand''s own current page is actively recruiting (''We''re inviting creators who share our values to join''), and no CollabFeed or SponsorRadar tracked campaign page for Native Union was found in searches.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandwiki.lazada.com.ph/native-union/', 'listing', 'general', 'Brand profile: Native Union is a design-focused consumer electronics accessories brand founded in 2009 by John Brunner and Igor Duc in Hong Kong, known for charging cables, wireless chargers, phone cases and device stands, with roots spanning Hong Kong, Paris and Los Angeles. Its own story page describes a Hong Kong-born brand with Parisian roots, and Village lists ''@nativeunion'' and ''nativeunion.com''.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 12, 12, 10, 5, '{"compensation": "Official page publishes 10% commission on every sale plus milestone gifts, but no uncapped language was found, so cap is unknown and scored below a verified uncapped program. Note the page''s inconsistent ''15% commission'' mention in the gifts section.", "contact_access": "Direct official creator application page on the brand''s own site, no intermediary or paywalled contact needed; no email is published on the fetched page, so email is null.", "credibility": "Established design-led brand founded in 2009, certified B Corp positioning in its own materials, with a live official creator program page fetched in full.", "niche_fit": "Premium technology accessories and charging (cables, wireless chargers, cases) with explicit creator niches including tech, lifestyle and travel, matching the batch category.", "opportunity_availability": "Official Creator Affiliate Program page is live and inviting applications today.", "ugc_evidence": "Low saturation is based on fetched evidence of a new, actively recruiting program: as of a November 14, 2026 check no creator route was listed at all, and no tracked CollabFeed/SponsorRadar campaign volume was found. Scored below Satechi because there is no tracked paid-post count to cite."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Baloo Living', 'https://balooliving.com/', 'Baloo Living is an American wellness and home goods brand founded in 2018 that makes quilted weighted blankets, bedding and sleep accessories from natural, chemical-free materials, notably 100% cotton with lead-free glass microbeads. Its own About page says its weighted blankets are designed to support deeper rest, reduce stress and help people reconnect with their natural rhythms.', 'United States', 'published') returning id into bid;
