  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'balooliving', 'https://www.instagram.com/balooliving/');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://getlasso.co/affiliate/baloo-living/', 'https://getlasso.co/affiliate/baloo-living/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.starterstory.com/stories/how-we-doubled-revenue-last-year-through-affiliate-marketing.', 'https://getlasso.co/affiliate/baloo-living/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Baloo Living Affiliate Program', 'https://getlasso.co/affiliate/baloo-living/', 'https://getlasso.co/affiliate/baloo-living/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/baloo-living/', 'listing', 'affiliate', 'LinkClicky listing: Baloo Living affiliate program via Impact, 6% per sale in that listing; other published listings differ (Lasso 10% per sale, Starter Story founder interview starting at 15%), so rates vary by channel/entry point.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.starterstory.com/stories/how-we-doubled-revenue-last-year-through-affiliate-marketing', 'creator_report', 'compensation', 'Starter Story follow-up interview with Baloo Living: ''we pay a starting commission of 15% on sales referred by those affiliates'' and affiliate is one of its strongest sales channels, built mainly with media partners. No cap, no-cap, unlimited-earnings or earnings-limit language was found on any fetched Baloo program/listing page, so commission_cap is unknown, not uncapped.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/baloo-living', 'listing', 'ugc_collab', 'Saturation evidence: Beacons Universe lists Baloo Living with only 19 creators who have posted about it all time, 21 mentions all time, and states ''No creator posted about Baloo Living in the 30 days to November 20, 2026'' (latest post found Nov 26, 2025). This is low creator saturation.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://balooliving.com/pages/about-us', 'official_site', 'general', 'Official About page: Baloo was founded by Elizabeth Grojean after time in Bali; ''We create products that help you reconnect with your natural rhythms... our weighted blankets are designed to support deeper rest, reduce stress.'' Beacons lists the brand as based in San Antonio, United States.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 12, 10, 8, 4, '{"compensation": "Highest published rate in this slice: starting 15% per Starter Story founder interview (other listings 6-10% by channel), but no explicit uncapped language found, so cap is unknown and compensation is not scored as uncapped.", "contact_access": "Joinable via published affiliate listings/network (Impact via LinkClicky, Lasso listing); no brand-owned affiliate application page was found in site search, so contact access is weaker than brands with their own page. No creator email was published on fetched pages, so email is null.", "credibility": "Multiple independent listings plus a founder interview in Starter Story and a Beacons Universe brand page agree the program and brand exist; rate disagreement across channels lowers credibility slightly.", "niche_fit": "Core HOME fit: weighted blankets, bedding and sleep accessories for the home, natural/cotton positioning.", "opportunity_availability": "Affiliate program is listed as active/joinable today via network listings; no follower minimum stated on the Lasso listing.", "ugc_evidence": "Strongest low-saturation evidence in the pool: Beacons Universe 19 creators all time, 0 creators in the last 30 days."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ekster', 'https://www.ekster.com', 'Ekster is a Dutch direct-to-consumer company, founded in 2016 and based in Amsterdam, that designs smart wallets, cardholders and everyday carry accessories with quick card access, RFID protection and optional tracking. It is a certified B Corporation and describes its products as better gear for life on the go. Its range now extends to travel bags and vacuum packing kits alongside the smart wallet line.', 'Netherlands', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'ekster', 'https://www.instagram.com/ekster');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'collaborations@ekster.com', 'https://www.ekster.com/en-ca/pages/ambassadors', 'https://support.ekster.com/en-US/how-can-i-collaborate-with-your-brand-492917', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.ekster.com/en-int/pages/affiliate-program.', 'https://www.ekster.com/en-ca/pages/ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ekster Ambassador Program — 10% commission on every sale via referral link', 'https://www.ekster.com/en-ca/pages/ambassadors', 'https://www.ekster.com/en-ca/pages/ambassadors', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ekster.com/en-ca/pages/ambassadors', 'official_site', 'affiliate', 'Fetched official Ekster Ambassadors page states: ''Become an ambassador — Earn 10% commission on every sale made through your referral link.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ekster.com/en-int/pages/affiliate-program', 'official_site', 'affiliate', 'Fetched official Ekster Affiliate Program page splits two routes: Ambassadors (social media / word of mouth; payment: ''Commissions & free products'') and Affiliates for media publications, apps and shopping platforms (payment: commission on sales), with the affiliate route linking to Rakuten Marketing (auth.rakutenmarketing.com).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ekster.com/en-int/pages/affiliate-program', 'official_site', 'compensation', 'No cap language was found on the fetched official affiliate/ambassador pages: no ''no cap'', ''unlimited earnings'', ''no limit on how much you can earn'' or FAQ answering an earnings-limit question appears. A third-party listing (GetLasso) separately reports 8% per sale, but no uncapped wording was found there either. Commission cap is therefore recorded as unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.babbl-labs.com/who-sponsors/ekster', 'creator_report', 'ugc_collab', 'Saturation evidence: Babbl Labs'' sponsorship tracking reports Ekster ''has sponsored at least 5 YouTube creators across 5 videos in the last 12 months'' (most recent Jun 2026, ~483K combined views). Five creators / five videos in 12 months is a small tracked footprint, supporting low saturation.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.ekster.com/en-US/how-can-i-collaborate-with-your-brand-492917', 'official_site', 'contact', 'Fetched official Ekster support page ''How can I collaborate with your brand?'' invites influencers to email collaborations@ekster.com with profile details, audience demographics and media kit, stating the brand ''continuously seek[s] vibrant and passionate influencers''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ekster.com/en-int/pages/about', 'official_site', 'general', 'Official Ekster story page: founders Olivier and Rick, two Dutch students, started Ekster after a Kickstarter campaign; ''We make smart wallets, bags and accessories that save you time''; Ekster is a B Corporation. Shopper''s affiliate listing records the programme country as Netherlands.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 12, 14, 9, 5, '{"compensation": "10% ambassador commission on the brand''s own page beats the 5% smart-home rates in this batch, but commission cap is unknown (no uncapped language found), so not top-scored.", "contact_access": "Best in batch: a published collaborations@ekster.com inbox for influencer pitches plus a public ambassador sign-up page.", "credibility": "Rate, routes and contact all come from Ekster''s own fetched pages; saturation count from a named sponsorship tracker.", "niche_fit": "Smart wallets with tracker cards and Find My-style carry tech fit personal tech well; less purely smart-home than Aqara, hence slightly lower.", "opportunity_availability": "Two joinable routes today: Ambassador programme and Rakuten affiliate programme, both linked from the official site.", "ugc_evidence": "Low saturation is evidenced (5 YouTube creators / 5 videos in 12 months per Babbl), with additional individual UGC posts observed, but tracked volume is small."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Wilderdog', 'https://www.wilderdog.com', 'Wilderdog is an outdoor dog gear and pet supplies company based in Sacramento, United States. Its own affiliate page says it has crafted durable outdoor gear for dogs for nearly a decade, backed by a lifetime warranty, and donates one pound of kibble for every purchase through its Purchase for a Pup program.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP.', 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Wilderdog Affiliate Program via AvantLink - apply from the official program page', 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'official_site', 'compensation', 'No cap language was found on the fetched official Wilderdog affiliate program page. The page invites bloggers/social creators to apply via AvantLink and describes commissions on qualifying sales, but contains no wording such as ''no cap'', ''unlimited earnings'' or ''no limit on how much you can earn'', and it does not publish a rate, so commission_cap is marked unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/wilderdog', 'listing', 'ugc_collab', 'Low saturation evidence from Beacons Universe (fetched): Wilderdog has posts from only 61 creators all time, 31 public posts in the last 12 months and only 1 sponsored post in the last 12 months (Ruby Rex, Nov 4, 2026) - the lowest sponsored-post count in this candidate pool, so creator_saturation is marked low. A published profile of the company also reported it works with about 10 ambassador photographers.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateworldforums.com/threads/wilderdog-affiliate-program-review.17608/', 'creator_report', 'affiliate', 'Published affiliate program review found in search reports 8% commission per sale and a 30-day cookie duration, with the program partnered with AvantLink. The brand''s own fetched page confirms the AvantLink partnership and the apply route but does not publish the rate itself, so the 8% is treated as publicly reported, not official.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wilderdog.com/pages/wilderdog-affiliate-program?srsltid=AfmBOopLCANaF1OUNfpzskqR6JvrAbflAZLpcDHftDEFR5R2SmoezxkP', 'official_site', 'general', 'Official page (fetched): ''Do you have a successful blog, website, or social where you share your adventures with your dog? Feel free to apply to our affiliate program here'' with an APPLY TO BE AN AFFILIATE link to AvantLink. Beacons Universe lists Wilderdog as based in Sacramento, United States, 1-50 employees, official website wilderdog.com. No verified social profile URL was fetched, so socials are left empty rather than constructed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 10, 10, 9, 4, '{"compensation": "8% per sale is only publicly reported in a published review and the official page publishes no rate; no uncapped language was found, so cap is unknown.", "contact_access": "Official program page with a direct AvantLink apply link, but no published affiliate email was found.", "credibility": "Program existence, network and apply route are verified on the brand''s own page and Beacons; the rate rests on a third-party review, hence 4 not 5.", "niche_fit": "Pure pets - durable outdoor dog gear for hiking/camping creators, a strong visual UGC niche.", "opportunity_availability": "Apply today from the official page via AvantLink, explicitly aimed at blogs and social creators.", "ugc_evidence": "Lowest saturation in the pool on Beacons: 61 creators all time and only 1 sponsored post in the last 12 months."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Aqara', 'https://www.aqara.com/', 'Aqara is a smart home brand under Lumi United Technology that sells sensors, hubs, cameras, locks and controls for connected homes. Its Awin programme describes its vision as comprehensive smart home products that are beautifully designed, affordable and easy to use. The brand was launched in 2016 and its parent is headquartered in Shenzhen, China.', 'China', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'aqara.smarthome.official', 'https://www.instagram.com/aqara.smarthome.official');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'adam@revil8.com', 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR.', 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Aqara UK Affiliate Programme on Awin — 5% commission, increases available for influencers', 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'affiliate_network', 'affiliate', 'Fetched Awin merchant page for Aqara UK states: ''5% commission on sales'', ''30-day cookie period'', ''£100 AOV'', and ''Commission increases available for content sites and influencers''. Programme is managed by Revil8; contact adam@revil8.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/99139?setLocale=fr_FR', 'affiliate_network', 'compensation', 'No cap language was found on the fetched Awin program page: no ''no cap'', ''unlimited earnings'', ''no limit on how much you can earn'' or FAQ answering an earnings-limit question appears. Commission cap is therefore recorded as unknown, not uncapped.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://findsponsors.so/brands/aqara', 'creator_report', 'ugc_collab', 'Saturation evidence: FindSponsors reports Aqara has paid only ''YouTube 5 creators · 8 posts'', sponsoring channels from 35k to 205k subscribers, with a mix of paid sponsorship (3), affiliate (4) and gifted product (1) deals. Five creators / eight posts is a small tracked creator footprint, supporting low saturation. The same page states: ''We haven''t found a public creator program page for Aqara.''', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cbinsights.com/company/lumi-united-technology', 'listing', 'general', 'CB Insights describes Aqara as specializing in smart home automation / IoT products including hubs, sensors, controllers, cameras, door locks, lighting and curtain controllers, founded in 2009 (parent Lumi) and based in Shenzhen, Guangdong. FindSponsors separately notes the Aqara brand was founded in 2016.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 10, 12, 8, 5, '{"compensation": "Published 5% on Awin is modest and commission cap is unknown (no uncapped language found), so scored mid-range; influencer rate increases are offered but unquantified.", "contact_access": "Joinable today via Awin and the fetched page names a programme manager email (adam@revil8.com) for collaborations.", "credibility": "Rate and terms come from the official Awin merchant listing fetched directly; saturation count comes from a named creator-tracking source.", "niche_fit": "Core smart home brand (sensors, hubs, cameras, locks) \u2014 direct fit for the smart home + personal tech slice.", "opportunity_availability": "Live Awin programme open to publishers/influencers today; no public brand-owned creator page, so route is network-only.", "ugc_evidence": "Low saturation is evidenced (5 creators, 8 sponsored posts on FindSponsors), but total tracked UGC volume is small, so evidence is real yet thin."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bearaby', 'https://bearaby.com/', 'Bearaby is a Brooklyn, United States-based home wellness brand making hand-knit weighted blankets (Nappers) from organic/ecological materials such as Tencel and cotton, without plastic beads or artificial fillers. It positions its blankets for sleep, calm and a cleaner, greener bedroom.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'home'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'mybearaby', 'https://www.instagram.com/mybearaby/');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://bearaby.eu/pages/affiliate', 'https://bearaby.eu/pages/affiliate', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/bearaby/.', 'https://bearaby.eu/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bearaby Affiliate Program', 'https://bearaby.eu/pages/affiliate', 'https://bearaby.eu/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bearaby.eu/pages/affiliate', 'official_site', 'affiliate', 'Brand''s own affiliate page (Bearaby EU official site): sign up with your details, ''Publish Napspiring Content'' on blog/website/newsletter/social with approved materials and offer links, then ''Start Earning Commission - For every Bearaby sale attributed to your links, you''ll start earning commission.'' No rate and no cap language are stated on this fetched page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/bearaby/', 'affiliate_network', 'compensation', 'LinkClicky listing: Bearaby uses the Impact affiliate platform, commission 4% per sale. BravoDM''s checked creator-program page likewise reports ''Bearaby affiliate program via Impact: 4% per sale per the LinkClicky listing'' and no follower minimum. No page fetched explicitly said ''no cap'', ''unlimited earnings'' or answered an earnings-limit FAQ, so commission_cap is unknown. The EU page''s line ''The more sales that get converted through your content, the more commission you''ll make'' is not explicit uncapped wording under the task rule.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bearaby.eu/pages/affiliate', 'official_site', 'compensation', 'Cap check: no cap/uncapped language was found on the fetched brand-owned affiliate page - it contains no ''no cap'', ''unlimited'', ''no limit on how much you can earn'' wording and no earnings-limit FAQ.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/bearaby', 'listing', 'ugc_collab', 'Saturation evidence: Beacons Universe lists Bearaby with 88 creators all time, only 4 creators in the last 30 days, 35 public posts in the last 12 months and only 5 sponsored posts in the last 12 months. This is low creator/sponsored saturation relative to TikTok Shop-heavy home brands in the pool with thousands of creators.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencerrate.com/affiliate-program/bearaby', 'listing', 'general', 'InfluencerRate description: Bearaby is a sustainable, eco-friendly company creating innovative weighted blankets made from organic/ecological materials such as Tencel or cotton, prioritising sleep and wellbeing. Beacons lists it as based in Brooklyn, United States, under Home & Garden.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 8, 12, 8, 4, '{"compensation": "Published rate is low at 4% per sale via Impact (LinkClicky/BravoDM); no explicit uncapped language found, so cap is unknown and compensation scores below Baloo''s 15%.", "contact_access": "Brand-owned affiliate page with a sign-up form route was fetched and is joinable today; no creator email published on that page, so email is null.", "credibility": "Brand-owned page plus Impact listing via two independent listings and a Beacons brand page corroborate the program.", "niche_fit": "Strong HOME fit: weighted blankets and home wellness/sleep products.", "opportunity_availability": "Own affiliate page is live with sign-up, content-publishing and earning steps; BravoDM notes no follower minimum stated.", "ugc_evidence": "Beacons Universe: 88 creators all time, 4 in last 30 days, only 5 sponsored posts in last 12 months - low saturation, though higher than Baloo''s 19."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fellow', 'https://fellowproducts.com', 'Fellow is a San Francisco, United States-based brand founded in 2013 that makes beautifully functional coffee and kitchen gear - including the Stagg pour-over kettle, Stagg EKG electric kettle, grinders and travel mugs - designed to bring the cafe experience home. Its own About page says its tools are designed in San Francisco and used around the world.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'home'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'instagram', 'fellowproducts', 'https://www.instagram.com/fellowproducts');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://compareepc.com/coffee-affiliate-programs/.', 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fellow Sponsorships & Affiliates - Creator / Brand Ambassador Program', 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'official_site', 'affiliate', 'Brand''s own Sponsorships & Affiliates page, fetched in full: ''We''re looking for content creators and brand ambassadors to help us spread the word about Fellow products and earn money through our affiliate program. You''ll gain early access to product releases, promotions, and exclusive marketing assets... From brewing beginners to pour-over pros, all levels of coffee knowledge are welcome!'' with an ''Apply to our affiliate program'' link to app.impact.com. No rate and no cap language are stated on this page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/coffee-affiliate-programs/', 'affiliate_network', 'compensation', 'CompareEPC coffee affiliate programs table: Fellow via Impact, commission 5%, EPC $0.82. Lasso''s Fellow Industries listing separately reports up to 4.88%. No page fetched explicitly said ''no cap'', ''unlimited earnings'' or answered an earnings-limit FAQ, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fellowproducts.com/pages/sponsorships?view=sponsorships', 'official_site', 'compensation', 'Cap check: no cap/uncapped language was found on the fetched brand-owned Sponsorships & Affiliates page - no ''no cap'', ''unlimited'', ''no limit'' wording and no earnings-limit FAQ.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/fellow', 'listing', 'ugc_collab', 'Saturation evidence (sponsored basis): Beacons Universe lists Fellow with 262 creators all time and 20 in the last 30 days for organic mentions, but only 3 sponsored posts in the last 12 months (most recent Nov 19, 2026). Paid/sponsored creator saturation is therefore low, while total organic mentions are moderate - scored accordingly, below Baloo and Bearaby.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fellowproducts.com/pages/about-us', 'official_site', 'general', 'Official About page: ''Fellow makes beautifully functional tools for any kitchen, designed in San Francisco and used around the world... We started Fellow in 2013 with a vision of bringing the cafe experience home'' and created the Stagg Pour-Over Kettle / Stagg EKG. Beacons lists Fellow as based in San Francisco, United States, under Home & Garden / Kitchenware.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 8, 13, 9, 5, '{"compensation": "Published rate 5% via Impact (CompareEPC; Lasso up to 4.88%) - modest, and no explicit uncapped language found, so cap is unknown.", "contact_access": "Best direct route in the slice: brand-owned Sponsorships & Affiliates page actively recruiting creators/ambassadors with a direct Apply link to Impact. No creator email published on that page, so email is null.", "credibility": "Brand-owned program page, Impact apply link, and independent network tables (CompareEPC, Lasso) plus a Beacons brand page all corroborate the program.", "niche_fit": "HOME fit via kitchen/coffee gear for the home (kettles, grinders, brewers, mugs); Beacons lists it under Home & Garden / Kitchenware, though it is coffee-led rather than bedding-led.", "opportunity_availability": "Official page is live and explicitly says it is looking for content creators and brand ambassadors, all coffee-knowledge levels welcome.", "ugc_evidence": "Low on sponsored evidence only: only 3 sponsored posts in the last 12 months on Beacons Universe, despite 262 creators mentioning it organically all time - hence a lower ugc_evidence score than Baloo (19) and Bearaby (88 / 5 sponsored)."}'::jsonb);
